import numpy as np
from netgen.meshing import Mesh,MeshPoint,FaceDescriptor,Element2D,Pnt
w=Path('work/carrier-interface-20261028');out=w/'netgen-carrier-native-005';assert out.exists()and not(out/'assessment.json').exists();source=w/'cgal-fe-subdivide-001/output/candidate.mesh64';start=time.monotonic()
